using Aspire.Hosting.Testing;
using Xunit;

namespace MyApp.AppHost.Tests;

public class AppHostTests
{
    [Fact]
    public async Task AppHost_StartsAndBecomesHealthy()
    {
        await using var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();
        await app.WaitForHealthyAsync();
    }

    [Fact]
    public async Task AppHost_AllResourcesAreRunning()
    {
        await using var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        await using var app = await appHost.BuildAsync();
        await app.StartAsync();
        await app.WaitForHealthyAsync();

        var resourceNotificationService = app.Services
            .GetRequiredService<ResourceNotificationService>();

        // Verify no resources are in a failed state
        var resources = app.Services.GetRequiredService<DistributedApplicationModel>().Resources;
        foreach (var resource in resources)
        {
            var snapshot = await resourceNotificationService
                .WaitForResourceAsync(resource.Name, KnownResourceStates.Running);
            Assert.Equal(KnownResourceStates.Running, snapshot.State?.Text);
        }
    }
}

